import {domLab,canvasLab} from './lab-kit.js';
import {axisFont} from './axis-font-data.js';
const c=(key,label,min,max,value,step=1)=>({key,label,min,max,value,step});
export const visualStudies=[];
function setup({root,values:v,kind,on}){const stage=root.querySelector('.lab-scene'),status=root.querySelector('.lab-status');let alt=false;return{update(){for(const [key,value]of Object.entries(v))stage.style.setProperty('--'+key,value);if(kind==='type-variable-axes'){root.querySelector('.axis-word').style.fontVariationSettings=`"wdth" ${v.width}, "slnt" ${v.slant}, "opsz" ${v.optical}`;status.textContent='図鑑オリジナルの実フォント · wdth / slnt / opsz'}if(kind==='color-palette'){root.querySelectorAll('.swatch').forEach((el,i)=>{const h=(v.hue+i*v.interval)%360;el.style.background=`hsl(${h} 40% ${i%2?65:38}%)`;el.textContent=Math.round(h)+'°'})}if(kind==='color-contrast'){const lum=x=>{x/=255;return x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4)},a=lum(v.foreground),b=lum(v.background),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);stage.style.background=`rgb(${v.background},${v.background},${v.background})`;stage.style.color=`rgb(${v.foreground},${v.foreground},${v.foreground})`;status.textContent=`コントラスト比 ${ratio.toFixed(2)}:1 · 通常文字のAA目安 ${ratio>=4.5?'達成':'未達'}`}if(kind==='type-line-break'||kind==='type-kinsoku')root.querySelector('.text-frame').style.width=v.width+'%';if(kind==='svg-icon-morph'){const p=v.progress/100,lines=root.querySelectorAll('line');lines[0].setAttribute('x1',35+10*p);lines[0].setAttribute('y1',35+10*p);lines[0].setAttribute('x2',85-10*p);lines[0].setAttribute('y2',35+40*p);lines[1].setAttribute('opacity',1-p);lines[2].setAttribute('x1',35+10*p);lines[2].setAttribute('y1',85-10*p);lines[2].setAttribute('x2',85-10*p);lines[2].setAttribute('y2',85-40*p);}},action(){alt=!alt;stage.classList.toggle('alternate',alt);status.textContent=alt?'比較する状態':'元の状態'}}}
function add(id,category,name,ja,desc,html,css,controls=[],extra={}){visualStudies.push(domLab({id,category,categories:[category],name,ja,description:desc,use:'文字・色・形の違いを比較し、意図に合う見せ方を選ぶとき。',tip:'数値や切り替えを変え、読みやすさと印象の変化を観察してください。',tags:[ja,category],source:'https://developer.mozilla.org/en-US/docs/Web/CSS',inputs:['adjust','pointer'],level:'applied',targets:[category==='type'?'text':'image'],contexts:['editorial'],...extra},setup,controls,html,'.lab-scene{height:180px;padding:12px;display:grid;align-content:center;gap:8px}.lab-scene p{margin:0;font-size:12px;line-height:1.7}.lab-scene small{font-size:10px}.lab-scene button{min-height:40px}'+css,{static:true,action:'比較を切り替える'}));}
add('type-variable-axes','type','Variable font axes','幅・傾斜・光学サイズを触る','実際の可変フォントの三つの軸を操作します。このオリジナル幾何学書体では、光学サイズで線の厚さと送り幅を変えています。','<div class="axis-word">EXPRESSION</div><small>WIDTH / SLANT / OPTICAL SIZE</small>',`@font-face{font-family:AxisStudy;src:url('${axisFont}') format('truetype');font-weight:400;font-stretch:75% 125%;font-style:oblique 0deg 12deg}.axis-word{font-family:AxisStudy,monospace;font-size:clamp(18px,5vw,34px);font-optical-sizing:none;line-height:2;white-space:nowrap}`,[c('width','幅 wdth',75,125,100),c('slant','傾斜 slnt',-12,0,0),c('optical','光学サイズ opsz',10,72,10)],{source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Fonts/Variable_fonts',tip:'光学サイズを変え、線と文字間の調整を観察。一般的なフォントの軸の範囲や設計とは異なります。'});
add('type-ruby','type','Ruby typography','読みに、小さな手がかりを添える','rubyとrtで、本文と読みを意味的にも視覚的にも結びつけます。','<p class="ruby-copy"><ruby>表現<rt>ひょうげん</rt></ruby>の<br><ruby>奥行<rt>おくゆ</rt></ruby>きを<ruby>探<rt>さぐ</rt></ruby>る。</p>','.ruby-copy{font-size:28px!important;line-height:2!important}.alternate rt{font-size:.7em}',[],{source:'https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/ruby'});
add('type-kinsoku','type','Japanese line breaking','行頭と行末の、整え方','厳格な日本語の禁則処理と、単純な文字単位の折り返しを比較します。','<div class="text-frame"><p>「表現の奥行き」を、もっと知りたい。小さな発見から、新しい景色へ。</p></div>','.text-frame{line-break:strict;word-break:normal;border:1px solid #aaa;padding:10px}.alternate .text-frame{line-break:anywhere}',[c('width','文章の幅 %',40,100,70)],{source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/line-break'});
add('type-line-break','type','Balanced headlines','改行の位置も、デザインする','見出しの各行の長さを均すtext-wrap:balanceを、通常の折り返しと比較します。','<div class="text-frame"><h3>Small discoveries change the way we see.</h3></div>','.text-frame h3{font:700 24px/1.2 Arial;margin:0;text-wrap:balance}.alternate h3{text-wrap:wrap}',[c('width','見出しの幅 %',45,100,80)],{source:'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/text-wrap'});
add('color-palette','color','Palette relationships','色同士の距離から配色する','色相環上の間隔を変え、隣り合う配色から離れた配色まで比較します。','<div class="swatches"><span class="swatch"></span><span class="swatch"></span><span class="swatch"></span><span class="swatch"></span></div>','.swatches{display:grid;grid-template-columns:repeat(4,1fr);height:110px}.swatch{display:grid;place-items:center;color:#fff;font:12px monospace;text-shadow:0 1px 3px #000}',[c('hue','基準の色相',0,359,200),c('interval','色相の間隔',0,180,30)]);
add('color-contrast','color','Contrast ratio','読める明暗差を確かめる','sRGBの相対輝度から、文字と背景のコントラスト比を算出します。','<h3 style="margin:0;font-size:30px">Read me.</h3><p>同じ文章を、違う明暗差で。</p>','',[c('foreground','文字の明るさ',0,255,40),c('background','背景の明るさ',0,255,240)],{source:'https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html',contexts:['accessibility'],tip:'比率はグレースケールのsRGBから計算。文字サイズや太さなど、他の読みやすさの条件も確認してください。'});
add('color-interpolation','gradient','Color-space interpolation','中間の色は、混ぜ方で変わる','同じ両端の色をsRGBとOKLCHで補間し、途中の彩度や明るさの違いを比べます。','<small>sRGB</small><div class="srgb"></div><small>OKLCH</small><div class="oklch"></div>','.srgb,.oklch{height:48px;background:linear-gradient(90deg,#ad405f,#2f8fba)}.oklch{background:linear-gradient(90deg in oklch,#ad405f,#2f8fba)}.alternate .srgb,.alternate .oklch{filter:grayscale(1)}',[],{categories:['gradient','color'],source:'https://developer.mozilla.org/en-US/docs/Web/CSS/color-interpolation-method',support:'OKLCH補間に非対応の環境では同じsRGBグラデーションで表示。'});
add('color-theme','color','Semantic theme','役割を保ちながら、明暗を変える','背景・本文・補助線の役割を変数にまとめ、ライトとダークで一緒に切り替えます。','<div class="theme-card"><small>FIELD NOTES</small><h3>After dark.</h3><p>明暗が変わっても、読む順番は同じ。</p></div>','.theme-card{--bg:#f7f7f3;--fg:#222;--line:#bbb;background:var(--bg);color:var(--fg);border:1px solid var(--line);padding:15px}.alternate .theme-card{--bg:#222;--fg:#eee;--line:#666}',[],{tags:['テーマ','ダークモード','配色']});
add('svg-icon-morph','svg','Icon state morph','メニューの線が、閉じる印へ','対応する線分の端点を補間し、二つの状態がつながって見えるアイコンをつくります。','<svg viewBox="0 0 120 120" height="130" role="img" aria-label="三本線から閉じる印へ"><g stroke="#222" stroke-width="6" stroke-linecap="round"><line x1="35" y1="35" x2="85" y2="35"/><line x1="35" y1="60" x2="85" y2="60"/><line x1="35" y1="85" x2="85" y2="85"/></g></svg>','',[c('progress','変形の進行 %',0,100,0)],{categories:['svg','morph','ui'],source:'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/line'});
function imageStudy({ctx,kind,values:v,state:s,pointer:p,event,status,line,text}){
 if(kind==='svg-freehand'){s.points??=[];if(event==='reset')s.points=[];if(p.down&&(event==='down'||event==='move'||event==='keyboard'))s.points.push([p.x,p.y]);if(event==='keyboard')s.points.push([p.x,p.y]);ctx.lineWidth=v.width;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#222';ctx.beginPath();s.points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();status('指で描く · 矢印キーでも描けます');return}
 for(let y=0;y<180;y+=2)for(let x=0;x<320;x+=2){let X=x,Y=y;if(kind==='image-displacement')X+=Math.sin(y*.06+v.amount*.05)*v.amount*.5;const disk=Math.hypot(X-150,Y-80)<48,lum=disk?.2:(.45+.4*Math.sin(X*.012+Y*.008));if(kind==='image-duotone'){const a=[30,35,40],b=[215,183,145];ctx.fillStyle=`rgb(${a.map((n,i)=>Math.round(n+(b[i]-n)*Math.pow(lum,v.amount/50))).join(',')})`}else{const L=kind==='image-posterize'?Math.round(lum*(v.amount-1))/(v.amount-1):lum;ctx.fillStyle=`rgb(${L*255},${L*255},${L*255})`}ctx.fillRect(x,y,2,2)}
 status(kind==='image-duotone'?'暗部と明部を二つの色へ写像':kind==='image-posterize'?'階調を減らして面のまとまりをつくる':'画像を読む座標を波でずらす');
}
for(const [id,category,name,ja,description,controls]of[
 ['image-duotone','image','Duotone mapping','二色で、画像の調子を整える','図鑑オリジナルの濃淡画像を二色の間へ写像します。',[c('amount','階調のカーブ',20,120,50)]],
 ['image-posterize','image','Posterization','階調を減らして、面を見つける','濃淡画像を指定した段階数へ量子化します。',[c('amount','階調の数',2,12,4)]],
 ['image-displacement','image','Image displacement','画像を読む場所を、ずらす','波形で横方向の参照座標を変え、元の構図をゆがめます。',[c('amount','ずれの大きさ',0,50,20)]],
 ['svg-freehand','gesture','Freehand stroke','指の軌跡を、一本の線にする','ポインターから集めた点をCanvasの丸い線で結びます。矢印キーにも対応します。',[c('width','線の太さ',1,18,5)]]
])visualStudies.push(canvasLab({id,category,categories:id==='svg-freehand'?['gesture','shape']:['image','texture'],name,ja,description,use:'ビジュアルの質感づくり、手描きの入力。',tip:'数値を変え、細部の情報がどう残るかを観察してください。',tags:[ja,'描画','画像'],source:'https://developer.mozilla.org/en-US/docs/Web/API/Canvas_API/Tutorial',level:'applied',targets:['image'],contexts:['portfolio']},imageStudy,controls,{animated:false,drag:id==='svg-freehand'}));
